module Etna.Gens.Hedgehog where

import           Data.List.NonEmpty (NonEmpty (..))
import           Hedgehog (Gen, MonadGen)
import qualified Hedgehog.Gen   as Gen
import qualified Hedgehog.Range as Range

import Etna.Properties

------------------------------------------------------------------------------
-- Upstream-style PBT generators (mirrors the QuickCheck module). Sized
-- 1..8 with key range [-100, 100]; closely follows
-- @nonempty-containers/test/Tests/Util.hs@. Distinct-key lists are
-- generated by drawing a Hedgehog @Set@ first then converting.

genKeyHH :: MonadGen m => m Int
genKeyHH = Gen.int (Range.linearFrom 0 (-100) 100)

genValHH :: MonadGen m => m Char
genValHH = Gen.element ['a' .. 'z']

genDistinctKeyListHH :: MonadGen m => Int -> m [Int]
genDistinctKeyListHH minSize = do
  -- Use Gen.set to dedupe; then ensure size is at least minSize. If
  -- the dedup drops below the floor we just use what we got (linearFrom
  -- towards minSize keeps small failures finding shrinks).
  s <- Gen.set (Range.exponential minSize 8) genKeyHH
  pure (foldr (:) [] s)

genNeKeyValListHH :: MonadGen m => Int -> m (NonEmpty (Int, Char))
genNeKeyValListHH minSize = do
  ks <- genDistinctKeyListHH minSize
  case ks of
    [] -> do
      k <- genKeyHH
      v <- genValHH
      pure ((k, v) :| [])
    (k : rest) -> do
      vs <- mapM (const genValHH) (k : rest)
      let pairs = zip (k : rest) vs
      case pairs of
        []       -> error "genNeKeyValListHH: empty"
        (p : ps) -> pure (p :| ps)

genNeIntListHH :: MonadGen m => Int -> m (NonEmpty Int)
genNeIntListHH minSize = do
  ks <- genDistinctKeyListHH minSize
  case ks of
    []       -> do
      k <- genKeyHH
      pure (k :| [])
    (k : ks') -> pure (k :| ks')

------------------------------------------------------------------------------

gen_delete_max_ne_map_keys_shrink :: Gen NeMapPairs
gen_delete_max_ne_map_keys_shrink = NeMapPairs <$> genNeKeyValListHH 1

gen_delete_max_ne_int_map_keys_shrink :: Gen NeIntMapPairs
gen_delete_max_ne_int_map_keys_shrink = NeIntMapPairs <$> genNeKeyValListHH 1

gen_delete_max_ne_set_shrink :: Gen NeSetElems
gen_delete_max_ne_set_shrink = NeSetElems <$> genNeIntListHH 1

gen_delete_max_ne_int_set_shrink :: Gen NeIntSetElems
gen_delete_max_ne_int_set_shrink = NeIntSetElems <$> genNeIntListHH 1

gen_intersperse_length_invariant :: Gen NeSeqElems
gen_intersperse_length_invariant = do
  n   <- Gen.int (Range.exponential 1 8)
  xs  <- mapM (const (Gen.int (Range.linearFrom 0 (-100) 100))) [1 .. n]
  sep <- Gen.int (Range.linearFrom 0 (-100) 100)
  case xs of
    []     -> error "gen_intersperse: empty"
    (x:rs) -> pure (NeSeqElems (x :| rs) sep)

gen_split_left_partition_at_upper_bound :: Gen SplitArgs
gen_split_left_partition_at_upper_bound =
  SplitArgs <$> genNeKeyValListHH 2

gen_is_submap_of_reflexive_and_key_exists :: Gen SubmapArgs
gen_is_submap_of_reflexive_and_key_exists = do
  a <- genNeKeyValListHH 1
  b <- genNeKeyValListHH 1
  pure (SubmapArgs a b)

gen_update_lookup_returns_original :: Gen UpdLookupArgs
gen_update_lookup_returns_original = do
  pairs <- genNeKeyValListHH 1
  mode  <- Gen.element [0, 1]
  pure (UpdLookupArgs pairs mode)
